   "scene": "hook",
   "text": "What happens when you ship Telo Ride with free, open-weight Hugging Face AI models running right inside the browser?",
   "caption": "What happens when you ship Telo Ride with free, open-weight Hugging Face AI models running right inside the browser?",
   "start": 2.581,
